    let mut d = debt(MK, 190, MK);
    let z = privacy_core::zero_hashes();
    let mut p0 = [0; DEPTH];
    for i in 1..DEPTH {
        p0[i] = z[i];
    }
    p0[0] = debt_leaf(MK, 0, 0, 190);
    d.low_key = 0;
    d.low_next_key = MK;
    d.low_next_index = 1;
    d.low_retained = 0;
    d.low_index = 0;
    d.low_path = p0;
    prove(clearing(s, d));
}

