// ---- Groundworks votes

/// s with lane A's output voting.
fn voting(s: St) -> St {
    let mut t = s;
    t.gw_out = stake_gw(NK, t.out.rho);
    let mut ex = 0;
    if !t.clear {
        for i in 0..2 {
            if t.ins[i].mk != 0 {
                ex = t.ins[i].ex;
                t.p_key = t.ins[i].mk;
                t.p_time = t.ins[i].mt;
                t.p_ex = ex;
            }
        }
    }
    t.w_out = t.out.amount - ex;
    t
}

